#!/usr/bin/env node
// Renderer bundle report: which sources make up each chunk, and what the first paint loads.
//   npx electron-vite build --sourcemap --outDir /tmp/ghost-build/out
//   node scripts/bundle-report.mjs /tmp/ghost-build/out/renderer [--top 25] [--chunk index]
// Attributes every generated byte of each .js chunk to its original source (via the source map),
// grouped by npm package (node_modules/<pkg>) or by src/renderer/src/<dir>. "Startup" = the entry
// chunk plus its static imports (what the browser must parse before React renders).
import { readFileSync, readdirSync, existsSync } from 'node:fs'
import { join, basename } from 'node:path'
import { decode } from '@jridgewell/sourcemap-codec'

const dir = process.argv[2]
if (!dir) throw new Error('usage: bundle-report.mjs <out/renderer> [--top N] [--chunk name]')
const arg = (k, d) => {
  const i = process.argv.indexOf(k)
  return i > 0 ? process.argv[i + 1] : d
}
const top = Number(arg('--top', 25))
const only = arg('--chunk', null)
const assets = join(dir, 'assets')
const files = readdirSync(assets)
const kb = (n) => (n / 1024).toFixed(1).padStart(8) + ' KB'

function group(src) {
  const nm = src.lastIndexOf('node_modules/')
  if (nm >= 0) {
    const rest = src.slice(nm + 13).split('/')
    return rest[0].startsWith('@') ? `${rest[0]}/${rest[1]}` : rest[0]
  }
  const m = src.match(/src\/renderer\/src\/(.*)$/)
  if (m) {
    const parts = m[1].split('/')
    return 'src/' + (parts.length > 2 ? parts.slice(0, 2).join('/') : parts.join('/'))
  }
  return src.replace(/^(\.\.\/)+/, '')
}

function attribute(file) {
  const code = readFileSync(join(assets, file), 'utf8')
  const mapFile = join(assets, file + '.map')
  const out = new Map()
  if (!existsSync(mapFile)) return { total: code.length, by: new Map([['(no map)', code.length]]) }
  const map = JSON.parse(readFileSync(mapFile, 'utf8'))
  const lines = code.split('\n')
  const decoded = decode(map.mappings)
  for (let li = 0; li < decoded.length; li++) {
    const segs = decoded[li]
    const len = (lines[li] ?? '').length
    for (let s = 0; s < segs.length; s++) {
      const seg = segs[s]
      const end = s + 1 < segs.length ? segs[s + 1][0] : len
      const key = seg.length > 1 ? group(map.sources[seg[1]]) : '(unmapped)'
      out.set(key, (out.get(key) ?? 0) + (end - seg[0]))
    }
  }
  return { total: code.length, by: out }
}

// Startup set: the entry script and the chunks it statically imports, transitively.
const html = readFileSync(join(dir, 'index.html'), 'utf8')
const entry = basename(html.match(/<script[^>]+src="[^"]*?([^/"]+\.js)"/)[1])
const startup = new Set()
const cssStartup = new Set()
const walk = (f) => {
  if (startup.has(f)) return
  startup.add(f)
  const code = readFileSync(join(assets, f), 'utf8')
  // Static imports only: `import … from "./x.js"` / `import "./x.js"` at module top level.
  for (const m of code.matchAll(/(?:^|[;\n}])\s*import\s*(?:[^'"()]*?from\s*)?["']\.\/([^"']+\.js)["']/g)) walk(m[1])
}
walk(entry)
for (const m of html.matchAll(/href="[^"]*?([^/"]+\.css)"/g)) cssStartup.add(m[1])

const js = files.filter((f) => f.endsWith('.js')).map((f) => ({ f, ...attribute(f) }))
js.sort((a, b) => b.total - a.total)
const sum = (xs) => xs.reduce((a, b) => a + b, 0)
const css = files.filter((f) => f.endsWith('.css')).map((f) => ({ f, size: readFileSync(join(assets, f)).length }))
const fonts = files.filter((f) => /\.(woff2?|ttf)$/.test(f))

console.log(`entry ${entry}`)
console.log(`JS total ${kb(sum(js.map((c) => c.total)))} in ${js.length} chunks; startup JS ${kb(sum(js.filter((c) => startup.has(c.f)).map((c) => c.total)))} (${[...startup].join(', ')})`)
console.log(`CSS total ${kb(sum(css.map((c) => c.size)))}; startup CSS ${kb(sum(css.filter((c) => cssStartup.has(c.f)).map((c) => c.size)))}`)
console.log(`fonts: ${fonts.length} files, ${kb(sum(fonts.map((f) => readFileSync(join(assets, f)).length)))} (${fonts.filter((f) => f.endsWith('.woff2')).length} woff2)`)
console.log('\nchunks:')
for (const c of js.slice(0, top)) console.log(`${kb(c.total)}  ${startup.has(c.f) ? '*' : ' '} ${c.f}`)
for (const c of js.filter((c) => (only ? c.f.startsWith(only) : startup.has(c.f)))) {
  console.log(`\n${c.f} by source:`)
  for (const [k, v] of [...c.by].sort((a, b) => b[1] - a[1]).slice(0, top)) console.log(`${kb(v)}  ${k}`)
}
